import csv, os, math
from collections import defaultdict

# Load DVOL
dvol_dir = 'loop-artifacts/stages/04/r1/cache/S1_binance_vision/dvol/'
dvol_files = [f for f in os.listdir(dvol_dir) if f.endswith('.json') or f.endswith('.csv')]
print(f"DVOL files: {dvol_files[:5]}")

# Try JSON first
dvol_data = []
for f in dvol_files:
    path = os.path.join(dvol_dir, f)
    try:
        with open(path) as fh:
            content = fh.read().strip()
            if content.startswith('[') or content.startswith('{'):
                import json
                data = json.loads(content)
                if isinstance(data, list):
                    for row in data:
                        if isinstance(row, dict):
                            ts = row.get('timestamp') or row.get('date') or row.get('t')
                            val = row.get('value') or row.get('dvol') or row.get('close')
                            if ts and val is not None:
                                dvol_data.append((int(ts), float(val)))
                elif isinstance(data, dict):
                    for k, v in data.items():
                        if isinstance(v, (int, float)):
                            dvol_data.append((int(k), float(v)))
            else:
                # CSV
                reader = csv.DictReader(fh)
                for row in reader:
                    ts_key = next((k for k in row if 'time' in k.lower() or 'date' in k.lower()), None)
                    val_key = next((k for k in row if 'dvol' in k.lower() or 'value' in k.lower() or 'close' in k.lower()), None)
                    if ts_key and val_key and row[ts_key] and row[val_key]:
                        dvol_data.append((int(float(row[ts_key])), float(row[val_key])))
    except Exception as e:
        pass

if dvol_data:
    dvol_data.sort()
    print(f"DVOL loaded: {len(dvol_data)} points, range {dvol_data[0][0]} to {dvol_data[-1][0]}")
else:
    print("DVOL: no data loaded, checking structure...")
    for f in dvol_files[:2]:
        path = os.path.join(dvol_dir, f)
        with open(path) as fh:
            print(f"--- {f} (first 200 chars) ---")
            print(fh.read(200))
